// ─── File: src/main/java/com/bank/aggregation/service/PortfolioAggregationService.java ───
package com.bank.aggregation.service;

import com.bank.aggregation.dto.AggregationReport;
import com.bank.aggregation.model.Trade;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;
import java.util.function.*;

@Service
@Slf4j
public class PortfolioAggregationService {

    private final List<Trade> trades = List.of(
        new Trade("RELIANCE", new BigDecimal("245050"), "SETTLED"),
        new Trade("TCS",      new BigDecimal("176000"), "SETTLED"),
        new Trade("RELIANCE", new BigDecimal("123750"), "SETTLED"),
        new Trade("HDFC",     new BigDecimal("330150"), "PENDING"),
        new Trade("TCS",      new BigDecimal("88750"),  "SETTLED")
    );

    public AggregationReport aggregate() {
        List<String> explanations = new ArrayList<>();

        // ═══ 1. BiFunction in Map.merge — aggregate amounts per symbol ═══
        Map<String, BigDecimal> totals = new HashMap<>();
        for (Trade trade : trades) {
            totals.merge(trade.symbol(), trade.amount(), BigDecimal::add);
            // merge(key, newValue, BiFunction<existingValue, newValue, mergedResult>)
            // RELIANCE: first 245050 (put). second 123750 → add(245050, 123750) = 368800
        }
        explanations.add("BiFunction in merge: BigDecimal::add merges duplicate keys");
        log.info("Merged totals: {}", totals);

        // ═══ 2. BiConsumer in Map.forEach — iterate key-value pairs ═══
        List<String> forEachOutput = new ArrayList<>();
        BiConsumer<String, BigDecimal> printEntry = (symbol, amount) ->
            forEachOutput.add(symbol + ": Rs." + amount.setScale(2, RoundingMode.HALF_UP));
        totals.forEach(printEntry);
        explanations.add("BiConsumer in forEach: (key, value) → void, iterates Map entries");

        // ═══ 3. BiFunction in Map.replaceAll — apply 5% interest ═══
        Map<String, BigDecimal> withInterest = new HashMap<>(totals);
        BiFunction<String, BigDecimal, BigDecimal> applyInterest = (symbol, amount) ->
            amount.multiply(new BigDecimal("1.05")).setScale(2, RoundingMode.HALF_UP);
        withInterest.replaceAll(applyInterest);
        // replaceAll(BiFunction<key, oldValue, newValue>) — transforms ALL values
        explanations.add("BiFunction in replaceAll: (key, oldValue) → newValue, transforms all entries");

        // ═══ 4. BiFunction in Map.compute — conditional update ═══
        Map<String, BigDecimal> computed = new HashMap<>(totals);
        computed.compute("WIPRO", (key, existing) ->
            existing == null ? new BigDecimal("50000") : existing.add(new BigDecimal("50000")));
        // WIPRO didn't exist → existing is null → returns 50000 (new entry)
        computed.compute("RELIANCE", (key, existing) ->
            existing == null ? new BigDecimal("50000") : existing.add(new BigDecimal("50000")));
        // RELIANCE exists → existing is 368800 → returns 418800
        explanations.add("BiFunction in compute: (key, existingOrNull) → newValue");

        // ═══ 5. BiPredicate — two-input condition ═══
        BiPredicate<Trade, BigDecimal> exceedsLimit = (trade, limit) ->
            trade.amount().compareTo(limit) > 0;
        BiPredicate<Trade, BigDecimal> exceedsAndSettled = exceedsLimit
            .and((trade, limit) -> trade.isSettled());

        BigDecimal limit = new BigDecimal("200000");
        List<String> biPredicateResults = trades.stream()
            .filter(t -> exceedsAndSettled.test(t, limit))
            .map(t -> t.symbol() + " Rs." + t.amount() + " exceeds Rs." + limit + " AND settled")
            .toList();
        explanations.add("BiPredicate: (Trade, BigDecimal) → boolean, composable with and/or/negate");

        // ═══ 6. BiConsumer composition with andThen ═══
        BiConsumer<String, BigDecimal> logAction = (s, a) -> log.info("LOG: {} = {}", s, a);
        BiConsumer<String, BigDecimal> auditAction = (s, a) -> log.info("AUDIT: {} = {}", s, a);
        BiConsumer<String, BigDecimal> combined = logAction.andThen(auditAction);
        totals.forEach(combined);  // both log AND audit for each entry
        explanations.add("BiConsumer.andThen: chain two actions on same (key, value) pair");

        return new AggregationReport(totals, forEachOutput, withInterest,
            biPredicateResults, explanations);
    }
}
```

