// ─── File: src/test/java/com/bank/aggregation/service/BiFunctionalInterfaceTest.java ───
package com.bank.aggregation.service;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import java.util.function.*;
import static org.assertj.core.api.Assertions.*;

class BiFunctionalInterfaceTest {

    // ═══ BiConsumer ═══
    @Test
    void biConsumerInMapForEach() {
        List<String> output = new ArrayList<>();
        Map.of("RELIANCE", 100, "TCS", 50)
            .forEach((symbol, qty) -> output.add(symbol + "=" + qty));
        assertThat(output).hasSize(2);
    }

    @Test
    void biConsumerAndThen() {
        StringBuilder log = new StringBuilder();
        BiConsumer<String, Integer> first = (k, v) -> log.append("[" + k + ":" + v + "]");
        BiConsumer<String, Integer> second = (k, v) -> log.append("!");
        first.andThen(second).accept("A", 1);
        assertThat(log.toString()).isEqualTo("[A:1]!");
    }

    // ═══ BiFunction ═══
    @Test
    void biFunctionInMapMerge() {
        Map<String, Integer> map = new HashMap<>();
        map.merge("A", 10, Integer::sum);  // A doesn't exist → put 10
        map.merge("A", 20, Integer::sum);  // A exists (10) → sum(10, 20) = 30
        assertThat(map.get("A")).isEqualTo(30);
    }

    @Test
    void biFunctionInMapReplaceAll() {
        Map<String, Integer> map = new HashMap<>(Map.of("A", 10, "B", 20));
        map.replaceAll((key, value) -> value * 2);  // double all values
        assertThat(map).containsEntry("A", 20).containsEntry("B", 40);
    }

    @Test
    void biFunctionInMapCompute() {
        Map<String, Integer> map = new HashMap<>();
        map.compute("A", (key, existing) -> existing == null ? 1 : existing + 1);
        map.compute("A", (key, existing) -> existing == null ? 1 : existing + 1);
        assertThat(map.get("A")).isEqualTo(2);
    }

    // ═══ BiPredicate ═══
    @Test
    void biPredicateTestsTwoArgs() {
        BiPredicate<String, Integer> longerThan = (s, len) -> s.length() > len;
        assertThat(longerThan.test("RELIANCE", 5)).isTrue();
        assertThat(longerThan.test("TCS", 5)).isFalse();
    }

    @Test
    void biPredicateComposition() {
        BiPredicate<Integer, Integer> greaterThan = (a, b) -> a > b;
        BiPredicate<Integer, Integer> bothPositive = (a, b) -> a > 0 && b > 0;
        BiPredicate<Integer, Integer> combined = greaterThan.and(bothPositive);

        assertThat(combined.test(10, 5)).isTrue();    // 10>5 AND both positive
        assertThat(combined.test(-1, -5)).isFalse();  // -1>-5 BUT not both positive
    }

    // ═══ Relationship to single-arg ═══
    @Test
    void biVersionAddsOneParameter() {
        Consumer<String> single = s -> {};              // 1 arg → void
        BiConsumer<String, Integer> bi = (s, i) -> {};  // 2 args → void

        Function<String, Integer> singleFn = String::length;          // 1 arg → result
        BiFunction<String, Integer, String> biFn = (s, i) -> s + i;  // 2 args → result

        Predicate<String> singlePred = String::isEmpty;                    // 1 arg → boolean
        BiPredicate<String, Integer> biPred = (s, i) -> s.length() > i;   // 2 args → boolean

        assertThat(singleFn.apply("TCS")).isEqualTo(3);
        assertThat(biFn.apply("TCS", 100)).isEqualTo("TCS100");
    }
}
